package com.jarvis.fa;
import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class BrainEngine{
 public interface Callback{void onResult(String reply);} private final SharedPreferences p; private final ExecutorService ex=Executors.newSingleThreadExecutor(); private final MemoryStore memoryStore;
 private static final String ENDPOINT="https://api.openai.com/v1/chat/completions"; private static final String MODEL="gpt-5.6-luna";
 public BrainEngine(Context c){p=c.getSharedPreferences("jarvis_data",Context.MODE_PRIVATE);memoryStore=new MemoryStore(c);if(p.getString("aiEndpoint","").isEmpty())p.edit().putString("aiEndpoint",ENDPOINT).apply();if(p.getString("aiModel","").isEmpty())p.edit().putString("aiModel",MODEL).apply();}
 public void configureOpenAI(String key){p.edit().putString("aiEndpoint",ENDPOINT).putString("aiModel",MODEL).putString("aiKey",key==null?"":key.trim()).apply();}
 public String model(){return p.getString("aiModel",MODEL);}
 public boolean isConfigured(){return !p.getString("aiKey","").trim().isEmpty();}
 public void test(Callback cb){ask("فقط بنویس: اتصال برقرار است","تست اتصال OpenAI",cb);}
 public void ask(String q,String memory,Callback cb){String n=q==null?"":q.trim();if(n.startsWith("یادت باشه")||n.startsWith("به خاطر بسپار")){String fact=n.replaceFirst("^(یادت باشه|به خاطر بسپار)\\s*","").trim();if(!fact.isEmpty()){memoryStore.remember(fact);memoryStore.addTurn("user",n);String r="یادم می‌ماند: "+fact;memoryStore.addTurn("assistant",r);cb.onResult(r);return;}}memoryStore.addTurn("user",n);if(!isConfigured()){String r="برای اتصال هوش مصنوعی، دکمه OpenAI را بزن و API Key خودت را وارد کن.";memoryStore.addTurn("assistant",r);cb.onResult(r);return;}ex.submit(()->{String r;try{String all=(memory==null?"":memory)+"\n\n"+memoryStore.context();r=call(n,all);}catch(Exception e){String m=e.getMessage()==null?"":e.getMessage();if(m.contains("401"))r="API Key معتبر نیست.";else if(m.contains("429"))r="اعتبار API کافی نیست یا محدودیت استفاده فعال شده است.";else r="اتصال هوش مصنوعی برقرار نشد. اینترنت و API Key را بررسی کن.";}memoryStore.addTurn("assistant",r);String out=r;new Handler(Looper.getMainLooper()).post(()->cb.onResult(out));});}
 private String call(String q,String memory)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(ENDPOINT).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(60000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("Authorization","Bearer "+p.getString("aiKey","").trim());JSONObject body=new JSONObject();body.put("model",MODEL);body.put("temperature",0.3);JSONArray ms=new JSONArray();ms.put(new JSONObject().put("role","system").put("content","تو JARVIS، دستیار شخصی فارسی‌زبان کاربر هستی. دقیق، کوتاه و اجرایی پاسخ بده. از حافظه برای پیوستگی استفاده کن. ادعا نکن عملی روی گوشی انجام شده مگر موتور محلی آن را اجرا کرده باشد."));if(memory!=null&&!memory.trim().isEmpty())ms.put(new JSONObject().put("role","system").put("content",memory));ms.put(new JSONObject().put("role","user").put("content",q));body.put("messages",ms);try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();InputStream is=code>=200&&code<300?c.getInputStream():c.getErrorStream();String txt=read(is);if(code<200||code>=300)throw new IOException("HTTP "+code+" "+txt);JSONObject root=new JSONObject(txt);JSONArray ch=root.optJSONArray("choices");if(ch==null||ch.length()==0)return "پاسخی دریافت نشد.";JSONObject msg=ch.getJSONObject(0).optJSONObject("message");return msg==null?"پاسخی دریافت نشد.":msg.optString("content","پاسخی دریافت نشد.");}
 private String read(InputStream is)throws Exception{if(is==null)return "";ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=is.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8");} public void shutdown(){ex.shutdownNow();}
}
